type ToolId='capacityGap'|'setupVariance';
type HistoryEntry={id:string;version:number;action:string;reason:string;actor:string;createdAt:string;snapshot?:{scenarioId?:string;moduleId?:string}};
type HistoryFeed={id:string;history:HistoryEntry[]};
type Props={data:Data;onDirtyChange?:(dirty:boolean)=>void;initialContext?:WorkspaceNavigationContext;onNavigate?:WorkspaceNavigate};
type RecordDraft={id?:string;expectedVersion?:number;scenarioId:string;moduleId:string;title:string;ownerId:string;start:string;due:string;priority:string;note:string;evidence:string;sourceOrderId:string;values:Record<string,string|number>};
type CalculationDraft={id?:string;expectedVersion?:number;scenarioId:string;toolId:ToolId;title:string;sourceOrderId:string;note:string;inputs:Record<string,string|number>};
type TransitionDraft={id:string;expectedVersion:number;operation:'advance'|'return'|'archive'|'restore';reason:string};
type WindowDraft={id?:string;expectedVersion:number;name:string;date:string;availableMinutes:string;reason:string};
type AllocationDraft={id?:string;expectedVersion:number;windowId:string;sourceOrderId:string;quantity:string;unitMinutes:string;basis:string};
type AllocationTransitionDraft={id:string;expectedVersion:number;operation:'confirm'|'cancel';reason:string};
type Editor={type:'record';draft:RecordDraft;base:string}|{type:'calculation';draft:CalculationDraft;base:string}|{type:'transition';draft:TransitionDraft;base:string}|{type:'window';draft:WindowDraft;base:string}|{type:'allocation';draft:AllocationDraft;base:string}|{type:'allocation-transition';draft:AllocationTransitionDraft;base:string};
type PendingRequest={action:string;body:Record<string,unknown>;token:string;success:()=>void};
const scenarios=planningScenarios as readonly Scenario[];
const toolDefinitions:Record<ToolId,{title:string;note:string;fields:{key:string;label:string;unit:string}[]}>={
 capacityGap:{title:'容量与负荷推演',note:'同一资源、同一时间窗口与同一工时口径；结果用于协调讨论。',fields:[{key:'available',label:'窗口可排工时',unit:'小时'},{key:'existing',label:'已占用工时',unit:'小时'},{key:'newDemand',label:'新增需求工时',unit:'小时'}]},
 setupVariance:{title:'换型用时差异',note:'核对同一次换型的计划与实际分钟，不据此推断设备或人员效率。',fields:[{key:'planned',label:'计划换型分钟',unit:'分钟'},{key:'actual',label:'实际换型分钟',unit:'分钟'}]},
};
const originalLinks:Record<string,{id:string;label:string}[]>={
 'capacity':[{id:'pmc',label:'PMC 排期总表'},{id:'orders',label:'动态订单总表'}],
 '02':[{id:'pmc-handoff',label:'PMC 交接工作台'},{id:'pmc',label:'PMC 排期总表'},{id:'orders',label:'动态订单总表'}],
 '03':[{id:'pmc',label:'PMC 排期总表'},{id:'department',label:'部门录入工作台'}],
 '04':[{id:'receiving',label:'供应商收货'},{id:'engineering-drawings',label:'工程画图部门'},{id:'pmc',label:'PMC 排期总表'}],
 '05':[{id:'pmc',label:'PMC 排期总表'},{id:'orders',label:'动态订单总表'}],
 '06':[{id:'finished-outsourcing',label:'成品外发跟进总表'},{id:'receiving',label:'供应商收货'}],
 '07':[{id:'pmc',label:'PMC 排期总表'},{id:'department',label:'部门录入工作台'}],
 '08':[{id:'pmc',label:'PMC 排期总表'},{id:'dashboard',label:'欠数与异常看板'}],
 '09':[{id:'engineering-drawings',label:'工程画图部门'},{id:'department',label:'部门录入工作台'}],
 '10':[{id:'orders',label:'动态订单总表'},{id:'mes',label:'MES 核对'},{id:'completed',label:'已完成订单档案'}],
};
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const shiftDate=(date:string,days:number)=>new Date(new Date(date+'T12:00:00Z').getTime()+days*86400000).toISOString().slice(0,10);
const fmt=(value:number)=>value.toLocaleString('zh-CN',{maximumFractionDigits:3});
const dateTime=(value:string)=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const moduleFor=(record:{scenarioId:string;moduleId:string})=>scenarios.find(scenario=>scenario.id===record.scenarioId)?.modules.find(module=>module.key===record.moduleId);
function calculate(toolId:ToolId,inputs:Record<string,string|number>):Record<string,number|null>{
 if(toolDefinitions[toolId].fields.some(field=>inputs[field.key]===''||inputs[field.key]===undefined||!Number.isFinite(Number(inputs[field.key]))||Number(inputs[field.key])<0))return {};
 if(toolId==='capacityGap'){const available=Number(inputs.available),total=Number(inputs.existing)+Number(inputs.newDemand);return {totalDemand:total,gapHours:Math.max(0,total-available),remainingHours:Math.max(0,available-total),loadPercent:available?total/available*100:null};}
 const planned=Number(inputs.planned),variance=Number(inputs.actual)-planned;return {varianceMinutes:variance,variancePercent:planned?variance/planned*100:null};
}
function resultRows(toolId:ToolId,result:Record<string,number|null>){const fields=toolId==='capacityGap'?[['totalDemand','合计需求工时','小时'],['gapHours','超出可排工时','小时'],['remainingHours','剩余可排工时','小时'],['loadPercent','需求 / 可排比例','%']]:[['varianceMinutes','实际减计划用时','分钟'],['variancePercent','用时偏差比例','%']];return fields.filter(([key])=>key in result).map(([key,label,unit])=>({key,label,unit,value:result[key]}));}
class PlanningRequestError extends Error{status:number;uncertain:boolean;constructor(message:string,status=0,uncertain=false){super(message);this.status=status;this.uncertain=uncertain;}}
async function api<T>(action:string,body?:unknown,signal?:AbortSignal):Promise<T>{
 let response:Response;try{response=await businessTeamFetch('/api/workspace/'+action,{method:body===undefined?'GET':'POST',headers:body===undefined?undefined:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal});}catch{if(signal?.aborted)throw new DOMException('请求已取消','AbortError');throw new PlanningRequestError('连接公司主机失败，请检查网络后重试。',0,body!==undefined);}
 let result:unknown;try{result=await response.json();}catch{throw new PlanningRequestError('服务器响应不完整，请重试。',response.status,body!==undefined);}
 if(!response.ok)throw new PlanningRequestError(typeof result==='object'&&result&&'error' in result?String(result.error):'本次操作未完成。',response.status,response.status>=500&&body!==undefined);
 if(body!==undefined&&(!result||typeof result!=='object'||!('ok' in result)||result.ok!==true||!('item' in result)||!result.item||typeof result.item!=='object'||!('id' in result.item)||typeof result.item.id!=='string'))throw new PlanningRequestError('保存响应缺少确认信息，请重试原请求核对结果。',response.status,true);
 return result as T;
}
function Field({label,children,wide=false}:{label:string;children:ReactElement<{id?:string;'aria-label'?:string}>;wide?:boolean}){const id=useId();return <div className={'planning-control-field'+(wide?' planning-control-field-wide':'')}><label htmlFor={id}>{label}</label>{cloneElement(children,{id,'aria-label':label})}</div>;}
function Empty({title,detail,children}:{title:string;detail:string;children?:ReactNode}){return <div className="planning-control-empty"><ClipboardList size={26} aria-hidden="true"/><h3>{title}</h3><p>{detail}</p>{children}</div>;}
function Modal({title,children,onClose,wide=false}:{title:string;children:ReactNode;onClose:()=>void;wide?:boolean}){return <div className="planning-control-backdrop"><section className={'planning-control-modal'+(wide?' planning-control-modal-wide':'')} role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><button type="button" aria-label="关闭窗口" onClick={onClose}><X size={19}/></button></header>{children}</section></div>;}
function Results({toolId,result}:{toolId:ToolId;result:Record<string,number|null>}){return <div className="planning-control-calculation-results">{resultRows(toolId,result).map(row=><div key={row.key}><span>{row.label}</span><b>{row.value===null?'—':fmt(row.value)}<small>{row.value===null?'':row.unit}</small></b></div>)}</div>;}

export function PlanningControlPanel({data,onDirtyChange,initialContext,onNavigate}:Props){
 const client=useQueryClient();
 const [scenarioId,setScenarioId]=useState(()=>scenarios.some(scenario=>scenario.id===initialContext?.tab)?initialContext!.tab!:'capacity');
 const [area,setArea]=useState('overview'),[search,setSearch]=useState(''),[stageFilter,setStageFilter]=useState('all'),[deadlineFilter,setDeadlineFilter]=useState('all');
 const [capacityWindowId,setCapacityWindowId]=useState(''),[showCancelled,setShowCancelled]=useState(false);
 const [editor,setEditor]=useState<Editor|null>(null),[selectedId,setSelectedId]=useState(initialContext?.recordId||''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[blocked,setBlocked]=useState(false),[uncertain,setUncertain]=useState<PendingRequest|null>(null),[sourceAcknowledged,setSourceAcknowledged]=useState(false);
 const [leave,setLeave]=useState<(()=>void)|null>(null);
 const inFlight=useRef(false),retry=useRef<{key:string;token:string}|null>(null),memberScope=useRef(data.me.id),locatorDone=useRef(''),requestedRecord=useRef(initialContext?.recordId||'');
 const dirty=!!editor&&JSON.stringify(editor.draft)!==editor.base;
 const isCapacity=scenarioId==='capacity';
 const query=useQuery<Feed>({queryKey:['planning-control',data.me.id,data.revision,scenarioId],queryFn:({signal})=>api<Feed>('planning-control-data?'+new URLSearchParams({scenarioId:isCapacity?'':scenarioId,includeArchived:'true'}),undefined,signal),retry:false});
 const feed=!blocked&&!query.isError?query.data:undefined,records=feed?.records||[],calculations=feed?.calculations||[];
 const scenario=scenarios.find(item=>item.id===scenarioId)||scenarios[0],live=records.filter(record=>!record.archived),archived=records.filter(record=>record.archived),current=records.find(record=>record.id===selectedId);
 const person=(id:string)=>feed?.members.find(member=>member.id===id)?.name||'已登记负责人';
 const historyQuery=useQuery<HistoryFeed>({queryKey:['planning-control-history',data.me.id,data.revision,selectedId,current?.version],queryFn:({signal})=>api<HistoryFeed>('planning-control-history?id='+encodeURIComponent(selectedId),undefined,signal),enabled:!!selectedId&&!!feed,retry:false});
 useEffect(()=>{const problem=historyQuery.error as PlanningRequestError|null;if(problem&&(problem.status===401||problem.status===403)){setBlocked(true);setError(problem.message);}},[historyQuery.error]);
 useEffect(()=>{if(!initialContext?.recordId||locatorDone.current===initialContext.recordId||!historyQuery.isSuccess)return;locatorDone.current=initialContext.recordId;const snapshot=historyQuery.data.history[0]?.snapshot;if(snapshot?.scenarioId&&scenarios.some(item=>item.id===snapshot.scenarioId)){setScenarioId(snapshot.scenarioId);setArea(snapshot.moduleId||'overview');}},[initialContext?.recordId,historyQuery.isSuccess,historyQuery.data]);
 useEffect(()=>{onDirtyChange?.(dirty||busy||!!uncertain);return()=>onDirtyChange?.(false);},[dirty,busy,uncertain,onDirtyChange]);
 useEffect(()=>{if(!dirty&&!busy&&!uncertain)return;const prevent=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue='';};window.addEventListener('beforeunload',prevent);return()=>window.removeEventListener('beforeunload',prevent);},[dirty,busy,uncertain]);
 useEffect(()=>{if(memberScope.current!==data.me.id){memberScope.current=data.me.id;setEditor(null);setSelectedId('');setUncertain(null);retry.current=null;setBlocked(false);setError('');setMessage('');}},[data.me.id]);
 useEffect(()=>{if(!query.isSuccess||query.isFetching||busy||uncertain||!editor?.draft.id)return;const allowed=editor.type==='record'||editor.type==='transition'?query.data.records:editor.type==='calculation'?query.data.calculations:editor.type==='window'?query.data.windows:query.data.allocations;if(!allowed.some(item=>item.id===editor.draft.id)){setEditor(null);setSelectedId('');setError('该记录已不在当前授权范围内，已关闭旧内容。');}},[query.isSuccess,query.isFetching,query.data,editor,busy,uncertain]);
 const guarded=(action:()=>void)=>{if(busy||uncertain){setError('请先确认当前请求的保存结果。');return;}if(dirty)setLeave(()=>action);else action();};
 useEffect(()=>{const id=initialContext?.recordId||'';if(id===requestedRecord.current)return;requestedRecord.current=id;const locate=()=>{setEditor(null);setSelectedId(id);locatorDone.current='';};if(dirty||busy||uncertain)setLeave(()=>locate);else locate();},[initialContext?.recordId,dirty,busy,uncertain]);
 const closeEditor=()=>guarded(()=>{setEditor(null);setError('');});
 const success=()=>{setEditor(null);setSelectedId('');setError('');setMessage('已保存并更新计划协同记录。');};
 async function submitRequest(request:PendingRequest){
  if(inFlight.current)return;inFlight.current=true;setBusy(true);setError('');setMessage('');
  let saved=false;
  try{await api(request.action,{...request.body,token:request.token});saved=true;retry.current=null;setUncertain(null);request.success();}
  catch(caught){const problem=caught as PlanningRequestError;setError(problem.message||'操作失败，请重试。');if(problem.status===401||problem.status===403){setBlocked(true);client.removeQueries({queryKey:['planning-control-history']});}if(problem.uncertain)setUncertain(request);}
  finally{inFlight.current=false;setBusy(false);}
  if(saved){try{await Promise.all([client.invalidateQueries({queryKey:['planning-control']}),client.invalidateQueries({queryKey:['planning-control-history']}),client.invalidateQueries({queryKey:['workspace']})]);}catch{setMessage('保存已经确认；列表刷新失败，请点击刷新读取最新结果。');}}
 }
 const mutate=(action:string,body:Record<string,unknown>)=>{const key=JSON.stringify([action,body]);if(retry.current?.key!==key)retry.current={key,token:clientId()};void submitRequest({action,body,token:retry.current.token,success});};
 const reopenData=async()=>{const result=await query.refetch();if(result.isSuccess){setBlocked(false);setError('');if(editor?.type==='record'&&editor.draft.id&&!result.data.records.some(record=>record.id===editor.draft.id)){setEditor(null);setSelectedId('');}}};
 function newRecord(module:PlanningModule){
  if(!feed?.canCreate)return;
  const draft:RecordDraft={expectedVersion:0,scenarioId,moduleId:module.key,title:'',ownerId:feed.members.some(member=>member.id===data.me.id)?data.me.id:'',start:today(),due:shiftDate(today(),7),priority:'普通',note:'',evidence:'',sourceOrderId:'',values:Object.fromEntries(module.fields.map(field=>[field.key,field.type==='select'?field.options?.[0]||'':'']))};
  setSourceAcknowledged(false);setError('');setEditor({type:'record',draft,base:JSON.stringify(draft)});
 }
 function editRecord(record:PlanningRecord){const draft:RecordDraft={id:record.id,expectedVersion:record.version,scenarioId:record.scenarioId,moduleId:record.moduleId,title:record.title,ownerId:record.ownerId,start:record.start,due:record.due,priority:record.priority,note:record.note,evidence:record.evidence,sourceOrderId:record.sourceOrderId,values:{...record.values}};setSelectedId('');setSourceAcknowledged(false);setError('');setEditor({type:'record',draft,base:JSON.stringify(draft)});}
 function transition(record:PlanningRecord,operation:TransitionDraft['operation']){const draft={id:record.id,expectedVersion:record.version,operation,reason:''};setSelectedId('');setError('');setEditor({type:'transition',draft,base:JSON.stringify(draft)});}
 function editCalculation(calculation?:Calculation,toolId:ToolId='capacityGap'){const selectedTool=calculation?.toolId||toolId;const draft:CalculationDraft={expectedVersion:0,...(calculation?{id:calculation.id,expectedVersion:calculation.version}:{}),scenarioId,toolId:selectedTool,title:calculation?.title||'',sourceOrderId:calculation?.sourceOrderId||'',note:calculation?.note||'',inputs:calculation?{...calculation.inputs}:Object.fromEntries(toolDefinitions[selectedTool].fields.map(field=>[field.key,'']))};setError('');setEditor({type:'calculation',draft,base:JSON.stringify(draft)});}
 function editWindow(window?:CapacityWindow){const draft:WindowDraft={expectedVersion:window?.version||0,...(window?{id:window.id}:{}),name:window?.name||'',date:window?.date||today(),availableMinutes:window?String(window.availableMinutes):'',reason:''};setError('');setEditor({type:'window',draft,base:JSON.stringify(draft)});}
 function editAllocation(allocation?:Allocation,windowId=''){const draft:AllocationDraft={expectedVersion:allocation?.version||0,...(allocation?{id:allocation.id}:{}),windowId:allocation?.windowId||windowId||capacityWindowId,sourceOrderId:allocation?.sourceOrderId||'',quantity:allocation?String(allocation.quantity):'',unitMinutes:allocation?String(allocation.unitMinutes):'',basis:allocation?.basis||''};setSourceAcknowledged(false);setError('');setEditor({type:'allocation',draft,base:JSON.stringify(draft)});}
 function transitionAllocation(allocation:Allocation,operation:'confirm'|'cancel'){const draft:AllocationTransitionDraft={id:allocation.id,expectedVersion:allocation.version,operation,reason:''};setError('');setEditor({type:'allocation-transition',draft,base:JSON.stringify(draft)});}
 function updateWindowDraft(patch:Partial<WindowDraft>){setEditor(value=>value?.type==='window'?{...value,draft:{...value.draft,...patch}}:value);}
 function updateAllocationDraft(patch:Partial<AllocationDraft>){setEditor(value=>value?.type==='allocation'?{...value,draft:{...value.draft,...patch}}:value);}
 function updateRecordDraft(patch:Partial<RecordDraft>){setEditor(value=>value?.type==='record'?{...value,draft:{...value.draft,...patch}}:value);}
 function updateCalculationDraft(patch:Partial<CalculationDraft>){setEditor(value=>value?.type==='calculation'?{...value,draft:{...value.draft,...patch}}:value);}
 const actionButtons=(record:PlanningRecord)=><div className="planning-control-actions"><button type="button" onClick={()=>setSelectedId(record.id)}>查看</button>{(record.canEdit||record.canProgress)&&<button type="button" onClick={()=>editRecord(record)}>{record.canEdit?'编辑':'登记进展'}</button>}{record.canAdvance&&<button type="button" className="planning-control-primary" onClick={()=>transition(record,'advance')}>推进阶段</button>}{record.canReturn&&<button type="button" onClick={()=>transition(record,'return')}>更正退回</button>}{record.canArchive&&<button type="button" onClick={()=>transition(record,'archive')}>归档</button>}{record.canRestore&&<button type="button" onClick={()=>transition(record,'restore')}>恢复</button>}</div>;
 const badge=(record:PlanningRecord)=><span className={'planning-control-badge'+(record.stage===3?' planning-control-badge-done':record.due<today()?' planning-control-badge-late':'')}>{record.status||moduleFor(record)?.statuses[record.stage]}{record.stage!==3&&record.due<today()?' · 逾期':''}</span>;
 const filtered=(rows:PlanningRecord[])=>rows.filter(record=>(stageFilter==='all'||String(record.stage)===stageFilter)&&(!search||[record.title,record.code,record.ownerName,record.note,record.sourceOrderLabel,...Object.values(record.values)].join(' ').toLocaleLowerCase().includes(search.trim().toLocaleLowerCase()))).sort((a,b)=>a.due.localeCompare(b.due));
 const currentRows=filtered(area==='archive'?archived:scenario.modules.some(module=>module.key===area)?live.filter(record=>record.moduleId===area):live).filter(record=>area!=='deadlines'||deadlineFilter==='all'||deadlineFilter==='late'&&record.stage!==3&&record.due<today()||deadlineFilter==='week'&&record.stage!==3&&record.due>=today()&&record.due<=shiftDate(today(),7));
 function recordTable(rows:PlanningRecord[],title='人工计划与核对记录'){
  return <section className="planning-control-card"><div className="planning-control-section-head"><h3>{title}</h3><span>{rows.length} 条</span></div>{rows.length?<div className="planning-control-table-scroll"><ExcelTable><thead><tr><th>事项 / 来源</th><th>登记数值与依据</th><th>负责人 / 期限</th><th>阶段</th><th>办理</th></tr></thead><tbody>{rows.map(record=><tr key={record.id}><td><button type="button" className="planning-control-text-button" onClick={()=>setSelectedId(record.id)}>{record.title}</button><small>{record.code} · {moduleFor(record)?.name}</small><small>{record.sourceOrderLabel||'独立协调事项'}</small>{record.sourceChanged&&<small className="planning-control-source-alert">原订单已更新，需重新核对</small>}</td><td><div className="planning-control-value-list">{moduleFor(record)?.fields.filter(field=>field.type==='number').map(field=><span key={field.key}>{field.label}：<b>{fmt(Number(record.values[field.key]||0))}</b> {field.unit}</span>)}</div><small>{record.evidence?'已登记阶段依据':'阶段依据待补充'}</small></td><td>{record.ownerName||person(record.ownerId)}<small>{record.due}</small><small>{record.priority}</small></td><td>{badge(record)}{record.archived&&<small>已归档</small>}</td><td>{actionButtons(record)}</td></tr>)}</tbody></ExcelTable></div>:<Empty title="当前范围暂无协调记录" detail="这里记录计划条件、人工核对与协调依据。可先选择业务模块登记真实事项。"/>}</section>;
 }
 function exportCsv(){
  const fieldDefinitions=Array.from(new Map(scenario.modules.flatMap(module=>module.fields.map(field=>[module.key+'.'+field.key,{module:module.key,field}] as const))).values());
  const header=['编号','场景','模块','事项','负责人','开始日期','截止日期','优先级','阶段','原订单ID','原订单参考','原订单版本','来源需重核','说明','依据','已归档',...fieldDefinitions.map(({module,field})=>`${scenario.modules.find(item=>item.key===module)?.name} / ${field.label}${field.unit?'（'+field.unit+'）':''}`)];
  const cell=(value:unknown)=>{let text=String(value??'');if(/^[\s]*[=+\-@]/.test(text)||/^[\t\r\n]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
  const rows=currentRows.map(record=>[record.code,scenario.edition,moduleFor(record)?.name,record.title,record.ownerName||person(record.ownerId),record.start,record.due,record.priority,record.status,record.sourceOrderId,record.sourceOrderLabel||'',record.sourceOrderVersion??'',record.sourceChanged?'是':'否',record.note,record.evidence,record.archived?'是':'否',...fieldDefinitions.map(({module,field})=>record.moduleId===module?record.values[field.key]:'')]);
  const url=URL.createObjectURL(new Blob(['\ufeff'+[header,...rows].map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`计划协同_${scenario.edition}_${area==='archive'?'归档':'未归档'}_${today()}.csv`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
 }
 function submitEditor(event:FormEvent){event.preventDefault();if(!editor||busy||uncertain)return;
  if(editor.type==='record'){const module=moduleFor(editor.draft);if(!module)return;mutate('planning-control-save',{...editor.draft,values:Object.fromEntries(module.fields.map(field=>[field.key,field.type==='number'?Number(editor.draft.values[field.key]):String(editor.draft.values[field.key]??'')]))});}
  if(editor.type==='calculation')mutate('planning-control-calculation-save',{...editor.draft,inputs:Object.fromEntries(toolDefinitions[editor.draft.toolId].fields.map(field=>[field.key,Number(editor.draft.inputs[field.key])]))});
  if(editor.type==='transition')mutate('planning-control-transition',{...editor.draft});
  if(editor.type==='window')mutate('planning-capacity-window-save',{...editor.draft,availableMinutes:Number(editor.draft.availableMinutes)});
  if(editor.type==='allocation')mutate('planning-capacity-allocation-save',{...editor.draft,quantity:Number(editor.draft.quantity),unitMinutes:Number(editor.draft.unitMinutes)});
  if(editor.type==='allocation-transition')mutate('planning-capacity-allocation-transition',{...editor.draft});
 }
 const editingRecord=editor?.type==='record'&&editor.draft.id?records.find(record=>record.id===editor.draft.id):undefined;
 const editingModule=editor?.type==='record'?moduleFor(editor.draft):undefined;
 const transitionRecord=editor?.type==='transition'?records.find(record=>record.id===editor.draft.id):undefined;
 const canManageFields=editor?.type==='record'?(editor.draft.id?!!editingRecord?.canEdit:!!feed?.canCreate):false;
 const editingWindow=editor?.type==='window'?feed?.windows.find(window=>window.id===editor.draft.id):undefined;
 const editingAllocation=editor?.type==='allocation'||editor?.type==='allocation-transition'?feed?.allocations.find(allocation=>allocation.id===editor.draft.id):undefined;
 const allocationSource=editor?.type==='allocation'?feed?.sourceOrders.find(order=>order.id===editor.draft.sourceOrderId):undefined;
 const allocationWindow=editor?.type==='allocation'?feed?.windows.find(window=>window.id===editor.draft.windowId):undefined;
 const allocationUnit=allocationSource?.unit||editingAllocation?.unit||'原订单单位';
 const windowHasAllocations=!!editingWindow&&!!feed?.allocations.some(item=>item.windowId===editingWindow.id&&item.status!=='cancelled');
 const allocationPreview=editor?.type==='allocation'&&editor.draft.quantity!==''&&editor.draft.unitMinutes!==''?Number(editor.draft.quantity)*Math.round(Number(editor.draft.unitMinutes)*1000)/1000:null;
 const allocationAvailable=allocationWindow?(Math.round(allocationWindow.remainingMinutes*1000)+(editingAllocation?.windowId===allocationWindow.id?Math.round(editingAllocation.loadMinutes*1000):0))/1000:null;
 const allocationSourceRemaining=allocationSource?.remainingQuantity===null||allocationSource?.remainingQuantity===undefined?null:Math.max(0,allocationSource.remainingQuantity-(feed?.allocations||[]).filter(item=>item.status!=='cancelled'&&item.sourceOrderId===allocationSource.id&&item.id!==editingAllocation?.id).reduce((sum,item)=>sum+item.quantity,0));
 const canEditForm=!!feed&&(editor?.type==='record'?editor.draft.id?!!(editingRecord?.canEdit||editingRecord?.canProgress):feed.canCreate:editor?.type==='calculation'?editor.draft.id?!!calculations.find(item=>item.id===editor.draft.id)?.canEdit:feed.canCalculate:editor?.type==='window'?editor.draft.id?!!editingWindow?.canEdit:feed.canManageCapacity:editor?.type==='allocation'?editor.draft.id?!!editingAllocation?.canEdit:feed.canManageCapacity:editor?.type==='allocation-transition'?editor.draft.operation==='confirm'?!!editingAllocation?.canConfirm:!!editingAllocation?.canCancel:editor?.type==='transition'&&transitionRecord?!!({advance:transitionRecord.canAdvance,return:transitionRecord.canReturn,archive:transitionRecord.canArchive,restore:transitionRecord.canRestore}[editor.draft.operation]):false);
 const errorBox=error&&<div className="planning-control-alert" role="alert">{error}</div>;
 const uncertainBox=uncertain&&<div className="planning-control-alert" role="alert"><p>保存结果尚未确认，当前输入已保留。请重试同一请求后再继续编辑。</p><button type="button" disabled={busy} onClick={()=>void submitRequest(uncertain)}>{busy?'正在核对…':'重试原请求'}</button></div>;
 if(!feed)return <section className="planning-control-panel" data-planning-control><div className="planning-control-card"><Empty title={query.isPending?'正在读取计划分析与协调记录':blocked?'当前权限需要重新核对':'暂时无法读取计划数据'} detail={query.isPending?'请稍候。':(error||(query.error as Error|undefined)?.message||'请重新读取当前授权范围。')+(editor?' 未提交输入已保留。':'')}>{!query.isPending&&<button type="button" disabled={query.isFetching} onClick={()=>void reopenData()}>重新读取</button>}</Empty>{uncertainBox}</div></section>;
 const areaTabs=[{id:'overview',label:'场景总览'},...scenario.modules.map(module=>({id:module.key,label:module.name})),{id:'deadlines',label:'办理期限'},{id:'archive',label:'归档记录'},{id:'calculations',label:'独立测算'}];
 return <section className="planning-control-panel" data-planning-control>
  <nav className="planning-control-tabs planning-control-scenarios" role="tablist" aria-label="生产计划场景"><button type="button" role="tab" aria-selected={isCapacity} data-scenario-id="capacity" onClick={()=>guarded(()=>{setScenarioId('capacity');setArea('overview');setSelectedId('');setEditor(null);setError('');setMessage('');})}>产能排程</button>{scenarios.map(item=><button type="button" role="tab" aria-selected={scenarioId===item.id} key={item.id} data-scenario-id={item.id} onClick={()=>guarded(()=>{setScenarioId(item.id);setArea('overview');setSearch('');setStageFilter('all');setSelectedId('');setEditor(null);setError('');setMessage('');})}>{item.edition.replace(/版$/,'')}</button>)}</nav>
  <header className="planning-control-hero"><div><span>{isCapacity?'有限产能 · 原订单引用 · 排程草案':'计划条件 · 人工核对 · 协作依据'}</span><h2>{isCapacity?'产能排程':scenario.edition.replace(/版$/,'')}</h2><p>{isCapacity?'按真实可用分钟安排订单数量，核对容量和未完工量后确认方案。':scenario.tagline}</p></div><div className="planning-control-hero-note"><ClipboardList size={21}/><span>{isCapacity?'当前授权范围':'本场景登记'}<b>{isCapacity?feed.allocations.filter(item=>item.status!=='cancelled').length+' 条有效分配':live.length+' 条未归档记录'}</b></span></div></header>
  <p className="planning-control-note">{isCapacity?'先登记资源与日期窗口，再选择原订单填写计划数量和单位工时。草案及已确认方案共同占用容量；确认只保存方案，不自动下达生产计划。':scenario.guide}</p>
  {onNavigate&&<div className="planning-control-original-links"><span>原有业务入口</span>{originalLinks[scenarioId]?.map(link=><button type="button" key={link.id} onClick={()=>guarded(()=>onNavigate(link.id))}>{link.label}<ArrowUpRight size={13}/></button>)}</div>}
  {!isCapacity&&<nav className="planning-control-tabs" role="tablist" aria-label="计划场景工作区">{areaTabs.map(item=><button type="button" role="tab" aria-selected={area===item.id} key={item.id} onClick={()=>guarded(()=>{setArea(item.id);setSearch('');setStageFilter('all');setSelectedId('');setEditor(null);setError('');})}>{item.label}</button>)}</nav>}
  {!editor&&errorBox}{!editor&&uncertainBox}{message&&<div className="planning-control-success" role="status"><CheckCircle2 size={17}/>{message}</div>}
  {selectedId&&!current&&historyQuery.isError&&<div className="planning-control-alert" role="alert">关联记录暂不可见：{(historyQuery.error as Error).message}<button type="button" onClick={()=>setSelectedId('')}>关闭提示</button></div>}
  {isCapacity&&<>
   <div className="planning-control-toolbar"><select aria-label="筛选产能窗口" value={capacityWindowId} onChange={event=>setCapacityWindowId(event.target.value)}><option value="">全部可见窗口</option>{feed.windows.map(window=><option key={window.id} value={window.id}>{window.date} · {window.name}</option>)}</select><label className="planning-control-check"><input type="checkbox" checked={showCancelled} onChange={event=>setShowCancelled(event.target.checked)}/>显示已取消分配</label><button type="button" disabled={query.isFetching} onClick={()=>void query.refetch()}><RefreshCw size={15}/>刷新</button>{feed.canManageCapacity&&<><button type="button" className="planning-control-primary" onClick={()=>editWindow()}><Plus size={15}/>新增产能窗口</button><button type="button" disabled={!feed.windows.length} onClick={()=>editAllocation()}><Plus size={15}/>分配订单</button></>}</div>
   <section className="planning-control-card"><div className="planning-control-section-head"><h3>产能窗口</h3><span>可用 / 占用 / 剩余 · 分钟</span></div>{feed.windows.length?<div className="planning-control-window-grid">{feed.windows.filter(window=>!capacityWindowId||window.id===capacityWindowId).map(window=><article key={window.id} data-capacity-window={window.id}><header><div><h3>{window.name}</h3><p>{window.date}</p></div>{window.canEdit&&<button type="button" onClick={()=>editWindow(window)}>调整窗口</button>}</header><dl><div><dt>可用分钟</dt><dd>{fmt(window.availableMinutes)}</dd></div><div><dt>占用分钟</dt><dd>{fmt(window.occupiedMinutes)}</dd></div><div><dt>剩余分钟</dt><dd>{fmt(window.remainingMinutes)}</dd></div></dl><div className="planning-control-progress" role="meter" aria-label={window.name+'容量占用'} aria-valuemin={0} aria-valuemax={window.availableMinutes||1} aria-valuenow={window.occupiedMinutes}><i style={{width:window.availableMinutes?Math.min(100,window.occupiedMinutes/window.availableMinutes*100)+'%':'0%'}}/></div>{feed.canManageCapacity&&<button type="button" onClick={()=>editAllocation(undefined,window.id)}>向此窗口分配订单<ChevronRight size={14}/></button>}</article>)}</div>:<Empty title="暂无可见产能窗口" detail={feed.canManageCapacity?'登记真实资源、日期和可用分钟，开始建立排程草案。':'当前账号没有可查看的窗口汇总；授权订单的分配记录会显示在下方。'}/>}</section>
   <section className="planning-control-card"><div className="planning-control-section-head"><h3>订单分配方案</h3><span>草案与已确认方案共同占用容量</span></div>{feed.allocations.some(item=>(showCancelled||item.status!=='cancelled')&&(!capacityWindowId||item.windowId===capacityWindowId))?<div className="planning-control-table-scroll"><ExcelTable><thead><tr><th>原订单 / 窗口</th><th>计划数量</th><th>单位工时</th><th>占用分钟</th><th>方案状态</th><th>核对依据 / 操作</th></tr></thead><tbody>{feed.allocations.filter(item=>(showCancelled||item.status!=='cancelled')&&(!capacityWindowId||item.windowId===capacityWindowId)).map(item=><tr key={item.id} data-capacity-allocation={item.id}><td><b>{item.sourceOrderLabel}</b><small>{item.windowDate||feed.windows.find(window=>window.id===item.windowId)?.date} · {item.windowName||feed.windows.find(window=>window.id===item.windowId)?.name||'已关联窗口'}</small>{onNavigate&&<button type="button" className="planning-control-text-button" onClick={()=>onNavigate('orders',{orderId:item.sourceOrderId})}>打开原订单<ArrowUpRight size={12}/></button>}</td><td>{fmt(item.quantity)} {item.unit}<small>原订单当前未完工：{item.remainingQuantity===null?'—':fmt(item.remainingQuantity)+' '+item.unit}</small></td><td>{fmt(item.unitMinutes)}<small>分钟 / {item.unit}</small></td><td>{fmt(item.loadMinutes)}</td><td><span className={'planning-control-badge'+(item.status==='confirmed'?' planning-control-badge-done':'')}>{item.status==='draft'?'草案':item.status==='confirmed'?'已确认方案':'已取消'}</span>{item.sourceChanged&&<small className="planning-control-source-alert">原订单已变化，需重新核对</small>}</td><td><p className="planning-control-basis">{item.basis}</p><div className="planning-control-actions">{item.canEdit&&<button type="button" onClick={()=>editAllocation(item)}>调整分配</button>}{item.canConfirm&&<button type="button" onClick={()=>transitionAllocation(item,'confirm')}>确认方案</button>}{item.canCancel&&<button type="button" onClick={()=>transitionAllocation(item,'cancel')}>取消分配</button>}</div></td></tr>)}</tbody></ExcelTable></div>:<Empty title="暂无符合筛选的订单分配" detail="分配数量和单位工时均由计划人员核对后填写；不会生成重复的生产执行台账。"/>}</section>
  </>}
  {!isCapacity&&<>
  {area!=='calculations'&&<div className="planning-control-toolbar"><label className="planning-control-search"><Search size={17}/><input type="search" aria-label="搜索计划协调记录" placeholder="搜索事项、编号、负责人或来源" value={search} onChange={event=>setSearch(event.target.value)}/></label><select aria-label="协调记录阶段" value={stageFilter} onChange={event=>setStageFilter(event.target.value)}><option value="all">全部阶段</option>{[0,1,2,3].map(stage=><option key={stage} value={stage}>第 {stage+1} 阶段{stage===3?'（已完成）':''}</option>)}</select><button type="button" onClick={()=>void query.refetch()} disabled={query.isFetching}><RefreshCw size={15}/>刷新</button><button type="button" onClick={exportCsv} disabled={!currentRows.length}><Download size={15}/>导出当前清单</button>{feed.canCreate&&scenario.modules.some(module=>module.key===area)&&<button type="button" className="planning-control-primary" onClick={()=>newRecord(scenario.modules.find(module=>module.key===area)!)}><Plus size={16}/>新增{scenario.modules.find(module=>module.key===area)!.name}</button>}</div>}
  {area==='overview'&&<>
   <div className="planning-control-metrics"><div><span>本场景待办理</span><strong>{live.filter(record=>record.stage!==3).length}<small>项</small></strong><p>未归档且未到最终阶段</p></div><div><span>逾期未完成</span><strong>{live.filter(record=>record.stage!==3&&record.due<today()).length}<small>项</small></strong><p>以登记的办理期限判断</p></div><div><span>未来 7 天到期</span><strong>{live.filter(record=>record.stage!==3&&record.due>=today()&&record.due<=shiftDate(today(),7)).length}<small>项</small></strong><p>今天至未来第 7 天</p></div><div><span>原订单待重核</span><strong>{live.filter(record=>record.sourceChanged).length}<small>项</small></strong><p>来源版本发生变化</p></div></div>
   <div className="planning-control-module-grid">{scenario.modules.map(module=><section className="planning-control-card" key={module.key}><div className="planning-control-section-head"><h3>{module.name}</h3><span>{live.filter(record=>record.moduleId===module.key).length} 条</span></div><div className="planning-control-module-body"><p>{module.statuses.join(' → ')}</p><div className="planning-control-actions"><button type="button" onClick={()=>setArea(module.key)}>查看记录<ChevronRight size={14}/></button>{feed.canCreate&&<button type="button" onClick={()=>newRecord(module)}><Plus size={14}/>新增</button>}</div></div></section>)}</div>
   {recordTable(currentRows.filter(record=>record.stage!==3).slice(0,8),'近期待办理 · 最多展示 8 项')}
  </>}
  {scenario.modules.some(module=>module.key===area)&&recordTable(currentRows,scenario.modules.find(module=>module.key===area)!.name)}
  {area==='deadlines'&&<><div className="planning-control-filter-pills">{[['all','全部期限'],['late','逾期'],['week','未来 7 天']].map(([id,label])=><button type="button" key={id} aria-pressed={deadlineFilter===id} onClick={()=>setDeadlineFilter(id)}>{label}</button>)}</div>{recordTable(currentRows,'办理期限 · 按截止日期排列')}</>}
  {area==='archive'&&<><p className="planning-control-note">本页仅显示当前场景的归档协调记录。恢复后回到原模块，保留原阶段与历史依据。</p>{recordTable(currentRows,'已归档的计划协调记录')}</>}
  {area==='calculations'&&<section className="planning-control-card"><div className="planning-control-section-head"><div><h3>独立测算</h3><p>手工输入条件，只保存分析记录</p></div></div><div className="planning-control-tools-grid">{(Object.keys(toolDefinitions) as ToolId[]).map(toolId=><article key={toolId}><h3>{toolDefinitions[toolId].title}</h3><p>{toolDefinitions[toolId].note}</p>{feed.canCalculate&&<button type="button" className="planning-control-primary" onClick={()=>editCalculation(undefined,toolId)}><Plus size={15}/>新增{toolDefinitions[toolId].title}</button>}</article>)}</div>{calculations.length?<div className="planning-control-calculations">{calculations.map(calculation=><article key={calculation.id}><header><div><h3>{calculation.title}</h3><p>{toolDefinitions[calculation.toolId].title}</p></div>{calculation.canEdit&&<button type="button" onClick={()=>editCalculation(calculation)}>调整输入</button>}</header><Results toolId={calculation.toolId} result={calculation.result}/><p>{calculation.note||'未填写测算说明'}</p>{calculation.sourceOrderLabel&&<p>原订单参考：{calculation.sourceOrderLabel}</p>}<small>更新于 {dateTime(calculation.updatedAt)}</small></article>)}</div>:<Empty title="本场景暂无已保存测算" detail="填写真实条件，零分母显示“—”。测算不会自动修改生产计划或业务台账。"/>}</section>}
  {area!=='calculations'&&<p className="planning-control-export-scope">CSV：{scenario.edition.replace(/版$/,'')} · {areaTabs.find(item=>item.id===area)?.label} · 当前账号授权及筛选范围 · {area==='archive'?'仅归档记录':'不含归档记录'}。数值单位按各字段保留。</p>}
  </>}
  <footer className="planning-control-footer">数据更新：{dateTime(feed.asOf)} · 协调记录不自动派工、扣库存、出库或记账</footer>

  {editor&&<Modal title={editor.type==='record'?(editor.draft.id?'编辑':'新增')+(editingModule?.name||'协调记录'):editor.type==='calculation'?(editor.draft.id?'调整':'新增')+toolDefinitions[editor.draft.toolId].title:editor.type==='window'?(editor.draft.id?'调整':'新增')+'产能窗口':editor.type==='allocation'?(editor.draft.id?'调整分配':'分配订单'):editor.type==='allocation-transition'?(editor.draft.operation==='confirm'?'确认排程方案':'取消订单分配'):'办理阶段与归档'} onClose={closeEditor} wide={editor.type!=='transition'&&editor.type!=='allocation-transition'}><form onSubmit={submitEditor}>
   {errorBox}{uncertainBox}{!canEditForm&&<div className="planning-control-alert" role="alert">当前记录的办理权限已变化，请重新读取后办理。未提交输入仍保留。</div>}
   <fieldset disabled={busy||!!uncertain||!canEditForm}>
    {editor.type==='window'&&<><div className="planning-control-form-grid"><Field label="资源 / 产能窗口名称" wide><input required maxLength={200} disabled={windowHasAllocations} value={editor.draft.name} onChange={event=>updateWindowDraft({name:event.target.value})} placeholder="例如实际产线、机台或班组"/></Field><Field label="窗口日期"><input required type="date" disabled={windowHasAllocations} value={editor.draft.date} onChange={event=>updateWindowDraft({date:event.target.value})}/></Field><Field label="可用产能（分钟）"><input required type="number" min={editingWindow?.occupiedMinutes||0} max="1000000" step="0.001" value={editor.draft.availableMinutes} onChange={event=>updateWindowDraft({availableMinutes:event.target.value})}/></Field><Field label="窗口变更原因" wide><textarea required={!!editor.draft.id} maxLength={3000} value={editor.draft.reason} onChange={event=>updateWindowDraft({reason:event.target.value})} placeholder={editor.draft.id?'说明资源或可用分钟变化的依据':'可记录可用分钟的核算依据'}/></Field></div><p className="planning-control-note">{windowHasAllocations?'本窗口已有有效分配，资源名称和日期已锁定。可用分钟不能低于当前占用 '+fmt(editingWindow!.occupiedMinutes)+' 分钟。':'按该资源当日实际可用分钟登记；系统不预设可用产能。'}</p></>}
    {editor.type==='allocation'&&<>
     {editingAllocation?.sourceChanged&&<div className="planning-control-alert"><p>原订单已更新。请重新核对未完工量、单位工时和分配依据，保存后再确认方案。</p><label className="planning-control-check"><input type="checkbox" checked={sourceAcknowledged} onChange={event=>setSourceAcknowledged(event.target.checked)}/>我已重新核对原订单，并确认本次分配依据</label></div>}
     <div className="planning-control-form-grid"><Field label="目标产能窗口" wide><select required value={editor.draft.windowId} onChange={event=>updateAllocationDraft({windowId:event.target.value})}><option value="">请选择真实产能窗口</option>{feed.windows.map(window=><option key={window.id} value={window.id}>{window.date} · {window.name} · 剩余 {fmt(window.remainingMinutes)} 分钟</option>)}</select></Field><Field label="关联原订单" wide><select required disabled={!!editor.draft.id} value={editor.draft.sourceOrderId} onChange={event=>updateAllocationDraft({sourceOrderId:event.target.value})}><option value="">选择当前有权查看的原订单</option>{feed.sourceOrders.map(order=><option key={order.id} value={order.id} disabled={order.remainingQuantity===null}>{order.label} · 未完工 {order.remainingQuantity===null?'未知':fmt(order.remainingQuantity)+' '+order.unit}</option>)}{editor.draft.sourceOrderId&&!feed.sourceOrders.some(order=>order.id===editor.draft.sourceOrderId)&&<option value={editor.draft.sourceOrderId}>{editingAllocation?.sourceOrderLabel||'已关联原订单'}</option>}</select></Field><Field label={'计划分配数量（'+allocationUnit+'）'}><input required type="number" min="1" max={allocationSourceRemaining??1000000} step="1" value={editor.draft.quantity} onChange={event=>updateAllocationDraft({quantity:event.target.value})}/></Field><Field label={'单位工时（分钟 / '+allocationUnit+'）'}><input required type="number" min="0.001" max="1000000" step="0.001" value={editor.draft.unitMinutes} onChange={event=>updateAllocationDraft({unitMinutes:event.target.value})}/></Field><Field label="分配核对依据" wide><textarea required maxLength={3000} value={editor.draft.basis} onChange={event=>updateAllocationDraft({basis:event.target.value})} placeholder="记录工时口径、资源、订单核对及安排依据"/></Field></div>
     <div className="planning-control-calculation-results"><div><span>本次计划占用</span><b>{allocationPreview===null?'—':fmt(allocationPreview)}<small>{allocationPreview===null?'':'分钟'}</small></b></div><div><span>本次可用窗口容量</span><b>{allocationAvailable===null?'—':fmt(allocationAvailable)}<small>{allocationAvailable===null?'':'分钟'}</small></b></div><div><span>原订单可继续分配</span><b>{allocationSourceRemaining===null?'—':fmt(allocationSourceRemaining)}<small>{allocationSourceRemaining===null?'':allocationUnit}</small></b></div></div>
     {allocationPreview!==null&&allocationAvailable!==null&&allocationPreview>allocationAvailable&&<div className="planning-control-alert" role="alert">本次计划占用超出窗口剩余容量，请调整数量或选择其他窗口。</div>}
     <p className="planning-control-note">计划占用 = 分配数量 × 每{allocationUnit}工时。当前草案原有占用已在“本次可用”中释放，保存时服务器会再次核对容量和原订单未完工量。</p>
    </>}
    {editor.type==='allocation-transition'&&editingAllocation&&<div className="planning-control-transition"><h3>{editingAllocation.sourceOrderLabel}</h3><p>{fmt(editingAllocation.quantity)} {editingAllocation.unit} · 占用 {fmt(editingAllocation.loadMinutes)} 分钟</p><div className="planning-control-transition-flow">{editingAllocation.status==='draft'?'草案':'已确认方案'}<ChevronRight size={18}/><b>{editor.draft.operation==='confirm'?'已确认方案':'取消分配并释放容量'}</b></div><Field label="方案办理依据" wide><textarea required maxLength={3000} value={editor.draft.reason} onChange={event=>{const reason=event.target.value;setEditor(current=>current?.type==='allocation-transition'?{...current,draft:{...current.draft,reason}}:current);}}/></Field><p className="planning-control-note">确认方案只记录人工排程决定。实际排期和生产办理仍在原有业务工作空间进行。</p></div>}
    {editor.type==='record'&&editingModule&&<>
     {editingRecord?.sourceChanged&&<div className="planning-control-alert"><p>原订单已更新。请打开原订单核对数量、版本及范围，再保存当前协调依据。</p>{canManageFields&&<label className="planning-control-check"><input type="checkbox" checked={sourceAcknowledged} onChange={event=>setSourceAcknowledged(event.target.checked)}/>我已重新核对原订单，并确认本次登记依据</label>}</div>}
     <div className="planning-control-form-grid">
      <Field label={editingModule.titleLabel||'协调事项名称'} wide><input required disabled={!canManageFields} maxLength={200} value={editor.draft.title} onChange={event=>updateRecordDraft({title:event.target.value})}/></Field>
      <Field label={editingModule.ownerLabel||'负责人'}><select required disabled={!canManageFields} value={editor.draft.ownerId} onChange={event=>updateRecordDraft({ownerId:event.target.value})}><option value="">请选择真实成员</option>{feed.members.map(member=><option key={member.id} value={member.id}>{member.name}</option>)}</select></Field>
      <Field label="优先级"><select disabled={!canManageFields} value={editor.draft.priority} onChange={event=>updateRecordDraft({priority:event.target.value})}>{['普通','重要','紧急'].map(value=><option key={value}>{value}</option>)}</select></Field>
      <Field label="开始日期"><input required type="date" disabled={!canManageFields} value={editor.draft.start} onChange={event=>updateRecordDraft({start:event.target.value})}/></Field><Field label={editingModule.dueLabel||'办理期限'}><input required type="date" disabled={!canManageFields} min={editor.draft.start} value={editor.draft.due} onChange={event=>updateRecordDraft({due:event.target.value})}/></Field>
      <Field label="关联原订单（可选，只读引用）" wide><select disabled={!canManageFields||!!editor.draft.id} value={editor.draft.sourceOrderId} onChange={event=>updateRecordDraft({sourceOrderId:event.target.value})}><option value="">不关联订单 · 独立协调事项</option>{feed.sourceOrders.map(order=><option key={order.id} value={order.id}>{order.label}</option>)}{editor.draft.sourceOrderId&&!feed.sourceOrders.some(order=>order.id===editor.draft.sourceOrderId)&&<option value={editor.draft.sourceOrderId}>{editingRecord?.sourceOrderLabel||'已有原订单引用'}</option>}</select></Field>
      {editor.draft.sourceOrderId&&onNavigate&&<div className="planning-control-form-help"><button type="button" onClick={()=>guarded(()=>onNavigate('orders',{orderId:editor.draft.sourceOrderId}))}>打开原订单核对<ArrowUpRight size={14}/></button><span>已建立的来源关联不能改绑。</span></div>}
      {editingModule.fields.map(field=><Field key={field.key} label={field.label+(field.unit?'（'+field.unit+'）':'')} wide={field.type==='text'&&field.label.length>10}>{field.type==='select'?<select required disabled={!canManageFields&&!editingRecord?.editableValueKeys.includes(field.key)} value={String(editor.draft.values[field.key]??'')} onChange={event=>{const value=event.target.value;setEditor(current=>current?.type==='record'?{...current,draft:{...current.draft,values:{...current.draft.values,[field.key]:value}}}:current);}}>{field.options?.map(option=><option key={option}>{option}</option>)}</select>:<input required type={field.type==='number'?'number':'text'} disabled={!canManageFields&&!editingRecord?.editableValueKeys.includes(field.key)} min={field.type==='number'?field.min??0:undefined} max={field.type==='number'?field.max??1000000:undefined} step={field.type==='number'?(field.integer?'1':'0.001'):undefined} maxLength={field.type==='number'?undefined:500} value={editor.draft.values[field.key]??''} onChange={event=>{const value=event.target.value;setEditor(current=>current?.type==='record'?{...current,draft:{...current.draft,values:{...current.draft.values,[field.key]:value}}}:current);}}/>}</Field>)}
      <Field label="业务说明与核对范围" wide><textarea maxLength={3000} value={editor.draft.note} onChange={event=>updateRecordDraft({note:event.target.value})} placeholder="记录计划口径、范围和需要协调的问题"/></Field>
      <Field label="阶段依据" wide><textarea maxLength={3000} value={editor.draft.evidence} onChange={event=>updateRecordDraft({evidence:event.target.value})} placeholder="记录人工核对的材料编号、已发生事实或来源"/></Field>
     </div><div className="planning-control-validation"><b>本模块数量与完成条件</b>{[...editingModule.checks,...editingModule.finishChecks].map((check,index)=><p key={index}>{check.message}</p>)}{!editingModule.checks.length&&!editingModule.finishChecks.length&&<p>按实际计划与实绩登记，用时允许有正负差异。</p>}</div>
    </>}
    {editor.type==='calculation'&&<><div className="planning-control-form-grid"><Field label="测算名称" wide><input required maxLength={200} value={editor.draft.title} onChange={event=>updateCalculationDraft({title:event.target.value})}/></Field><Field label="关联原订单（可选，只读引用）" wide><select disabled={!!editor.draft.id} value={editor.draft.sourceOrderId} onChange={event=>updateCalculationDraft({sourceOrderId:event.target.value})}><option value="">独立测算，不关联订单</option>{feed.sourceOrders.map(order=><option key={order.id} value={order.id}>{order.label}</option>)}</select></Field>{toolDefinitions[editor.draft.toolId].fields.map(field=><Field key={field.key} label={field.label+'（'+field.unit+'）'}><input required type="number" min="0" max="1000000" step="0.001" value={editor.draft.inputs[field.key]??''} onChange={event=>{const value=event.target.value;setEditor(current=>current?.type==='calculation'?{...current,draft:{...current.draft,inputs:{...current.draft.inputs,[field.key]:value}}}:current);}}/></Field>)}<Field label="输入来源与测算说明" wide><textarea maxLength={3000} value={editor.draft.note} onChange={event=>updateCalculationDraft({note:event.target.value})}/></Field></div><Results toolId={editor.draft.toolId} result={calculate(editor.draft.toolId,editor.draft.inputs)}/><p className="planning-control-note">{toolDefinitions[editor.draft.toolId].note} 零分母显示“—”；保存后形成独立分析记录。</p></>}
    {editor.type==='transition'&&transitionRecord&&<div className="planning-control-transition"><h3>{transitionRecord.title}</h3><p>{moduleFor(transitionRecord)?.name}</p><div className="planning-control-transition-flow">{transitionRecord.status}<ChevronRight size={18}/><b>{editor.draft.operation==='advance'?moduleFor(transitionRecord)?.statuses[transitionRecord.stage+1]:editor.draft.operation==='return'?'退回可编辑阶段':editor.draft.operation==='archive'?'移入归档':'恢复原模块'}</b></div><Field label={editor.draft.operation==='advance'?'本阶段核对依据（必填）':'更正或归档依据（必填）'} wide><textarea required maxLength={3000} value={editor.draft.reason} onChange={event=>{const reason=event.target.value;setEditor(current=>current?.type==='transition'?{...current,draft:{...current.draft,reason}}:current);}}/></Field><p className="planning-control-note">本操作记录人工计划办理事实，不代表自动下达生产、仓库收发或财务过账。</p></div>}
   </fieldset><div className="planning-control-modal-actions"><span>{dirty?'有尚未保存的输入':'原业务记录保持只读引用'}</span><button type="button" disabled={busy||!!uncertain} onClick={closeEditor}>取消</button><button className="planning-control-primary" disabled={busy||!!uncertain||!canEditForm||(editor.type==='record'&&!!editingRecord?.sourceChanged&&canManageFields&&!sourceAcknowledged)||(editor.type==='allocation'&&((!!editingAllocation?.sourceChanged&&!sourceAcknowledged)||(allocationPreview!==null&&allocationAvailable!==null&&allocationPreview>allocationAvailable)||allocationSourceRemaining===null))}>{busy?'正在保存…':editor.type==='transition'||editor.type==='allocation-transition'?'确认办理':'保存'}</button></div>
  </form></Modal>}
  {current&&!editor&&<Modal title="协调记录与历史依据" onClose={()=>setSelectedId('')} wide><div className="planning-control-detail"><div className="planning-control-detail-title"><h3>{current.title}</h3>{badge(current)}</div><dl><div><dt>模块 / 编号</dt><dd>{moduleFor(current)?.name} · {current.code}</dd></div><div><dt>负责人</dt><dd>{current.ownerName||person(current.ownerId)}</dd></div><div><dt>开始 / 办理期限</dt><dd>{current.start} → {current.due}</dd></div><div><dt>优先级</dt><dd>{current.priority}</dd></div>{current.sourceOrderId&&<div><dt>关联原订单</dt><dd>{current.sourceOrderLabel}{onNavigate&&<button type="button" onClick={()=>onNavigate('orders',{orderId:current.sourceOrderId})}>打开原订单<ArrowUpRight size={13}/></button>}</dd></div>}{moduleFor(current)?.fields.map(field=><div key={field.key}><dt>{field.label}</dt><dd>{field.type==='number'?fmt(Number(current.values[field.key]||0)):String(current.values[field.key]??'—')} {field.unit||''}</dd></div>)}</dl>{current.sourceChanged&&<div className="planning-control-alert">原订单版本已更新，请由管理人员重核登记依据后再推进。</div>}<section><h4>业务说明与口径</h4><p>{current.note||'未填写'}</p></section><section><h4>本阶段依据</h4><p>{current.evidence||'尚未登记阶段依据'}</p></section>{actionButtons(current)}<section className="planning-control-history"><h4><History size={16}/>操作与依据历史</h4>{historyQuery.isError?<div className="planning-control-alert" role="alert">{(historyQuery.error as Error).message}<button type="button" onClick={()=>void historyQuery.refetch()}>重试历史记录</button></div>:historyQuery.isPending?<p>正在读取历史记录…</p>:historyQuery.data?.history.length?historyQuery.data.history.map(entry=><article key={entry.id}><b>{entry.action}</b><small>{entry.actor} · {dateTime(entry.createdAt)}</small><p>{entry.reason||'未附加说明'}</p></article>):<p>暂无历史记录。</p>}</section></div></Modal>}
  {leave&&<Modal title="保留或放弃未保存输入" onClose={()=>setLeave(null)}><div className="planning-control-discard"><p>当前表单尚未保存，继续编辑可保留全部输入。</p><div className="planning-control-modal-actions"><button type="button" onClick={()=>setLeave(null)}>继续编辑</button><button type="button" disabled={busy||!!uncertain} onClick={()=>{const action=leave;setLeave(null);setEditor(null);setError('');onDirtyChange?.(false);action();}}>放弃输入并继续</button></div></div></Modal>}
 </section>;
}
